import{_ as i,a0 as o,w as a,s as l,ao as c,I as r,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"Linux有问必答：如何为CentOS 7配置静态IP地址 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何为CentOS 7配置静态IP地址 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何为CentOS 7配置静态IP地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何为CentOS 7配置静态IP地址 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7","title":"Linux有问必答：如何为CentOS 7配置静态IP地址","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to configure a static IP address on CentOS 7.md"};function m(f,t,u,g,C,x){const s=o("Link");return a(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux有问必答-如何为centos-7配置静态ip地址" tabindex="-1">Linux有问必答：如何为CentOS 7配置静态IP地址 <a class="header-anchor" href="#linux有问必答-如何为centos-7配置静态ip地址" aria-label="Permalink to “Linux有问必答：如何为CentOS 7配置静态IP地址”">​</a></h1><blockquote><p><strong>问题</strong>：在CentOS 7上，我想要将我其中一个网络接口从DHCP改为静态IP地址配置，如何才能永久为CentOS或RHEL 7上的网络接口分配静态IP地址？</p></blockquote><p>如果你想要为CentOS 7中的某个网络接口设置静态IP地址，有几种不同的方法，这取决于你是否想要使用网络管理器。</p><p>网络管理器（Network Manager）是一个动态网络的控制器与配置系统，它用于当网络设备可用时保持设备和连接开启并激活。默认情况下，CentOS/RHEL 7安装有网络管理器，并处于启用状态。</p><p>使用下面的命令来验证网络管理器服务的状态：</p><pre><code>$ systemctl status NetworkManager.service
</code></pre><p>运行以下命令来检查受网络管理器管理的网络接口：</p><pre><code>$ nmcli dev status 
</code></pre><p><img src="https://farm4.staticflickr.com/3861/15295802711_a102a3574d_z.jpg" alt=""></p><p>如果某个接口的nmcli的输出结果是“已连接”（如本例中的enp0s3），这就是说该接口受网络管理器管理。你可以轻易地为某个特定接口禁用网络管理器，以便你可以自己为它配置一个静态IP地址。</p><p>下面将介绍<strong>在CentOS 7上为网络接口配置静态IP地址的两种方式</strong>，在例子中我们将对名为enp0s3的网络接口进行配置。</p><h3 id="不使用网络管理配置静态ip地址" tabindex="-1">不使用网络管理配置静态IP地址 <a class="header-anchor" href="#不使用网络管理配置静态ip地址" aria-label="Permalink to “不使用网络管理配置静态IP地址”">​</a></h3><p>进入/etc/sysconfig/network-scripts目录，找到该接口的配置文件（ifcfg-enp0s3）。如果没有，请创建一个。</p><p><img src="https://farm4.staticflickr.com/3911/15112399977_d3df8e15f5_z.jpg" alt=""></p><p>打开配置文件并编辑以下变量：</p><p><img src="https://farm4.staticflickr.com/3880/15112184199_f4cbf269a6.jpg" alt=""></p><p>在上图中，“NM_CONTROLLED=no”表示该接口将通过该配置文件进行设置，而不是通过网络管理器进行管理。“ONBOOT=yes”告诉我们，系统将在启动时开启该接口。</p><p>保存修改并使用以下命令来重启网络服务：</p><pre><code># systemctl restart network.service
</code></pre><p>现在验证接口是否配置正确：</p><pre><code># ip add 
</code></pre><p><img src="https://farm6.staticflickr.com/5593/15112397947_ac69a33fb4_z.jpg" alt=""></p><h3 id="使用网络管理器配置静态ip地址" tabindex="-1">使用网络管理器配置静态IP地址 <a class="header-anchor" href="#使用网络管理器配置静态ip地址" aria-label="Permalink to “使用网络管理器配置静态IP地址”">​</a></h3><p>如果你想要使用网络管理器来管理该接口，你可以使用nmtui（网络管理器文本用户界面），它提供了在终端环境中配置配置网络管理器的方式。</p><p>在使用nmtui之前，首先要在/etc/sysconfig/network-scripts/ifcfg-enp0s3中设置“NM_CONTROLLED=yes”。</p><p>现在，请按以下方式安装nmtui。</p><pre><code># yum install NetworkManager-tui
</code></pre><p>然后继续去编辑enp0s3接口的网络管理器配置：</p><pre><code># nmtui edit enp0s3 
</code></pre><p>在下面的屏幕中，我们可以手动输入与/etc/sysconfig/network-scripts/ifcfg-enp0s3中所包含的内容相同的信息。</p><p>使用箭头键在屏幕中导航，按回车选择值列表中的内容（或填入想要的内容），最后点击屏幕底部右侧的确定按钮。</p><p><img src="https://farm4.staticflickr.com/3878/15295804521_4165c97828_z.jpg" alt=""></p><p>最后，重启网络服务。</p><pre><code># systemctl restart network.service
</code></pre><p>好了，现在一切都搞定了。</p><hr>`,36)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"http://ask.xmodulo.com/configure-static-ip-address-centos7.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/configure-static-ip-address-centos7.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),n(s,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const O=i(d,[["render",m]]);export{P as __pageData,O as default};
